package br.com.heroisdeplantao;
import br.com.heroisdeplantao.modelo.*;import br.com.heroisdeplantao.repositorio.*;import br.com.heroisdeplantao.servico.*;import java.time.*;
public class App {private static int aprovados=0;private static void verificar(boolean condicao,String descricao){if(!condicao)throw new AssertionError("FALHOU: "+descricao);aprovados++;System.out.println("OK - "+descricao);}private static void deveFalhar(Runnable acao,String descricao){boolean falhou=false;try{acao.run();}catch(IllegalArgumentException|IllegalStateException ex){falhou=true;}verificar(falhou,descricao);}
 public static void main(String[] args){PacienteServico pacientes=new PacienteServico(new RepositorioEmMemoria<>());MedicoServico medicos=new MedicoServico(new RepositorioEmMemoria<>());ConsultaServico consultas=new ConsultaServico(new RepositorioEmMemoria<>());ConvenioServico convenios=new ConvenioServico(new RepositorioEmMemoria<>());ProntuarioServico prontuarios=new ProntuarioServico(new RepositorioEmMemoria<>());
 Paciente p=new Paciente(1,"Ana Silva","12345678900",LocalDate.of(1997,5,14),"F","11999999999","ana@exemplo.com","Rua Exemplo","Penicilina",false);Medico m=new Medico(1,"Dr. Carlos","CRM-12345","Clínica Geral","11888888888","carlos@exemplo.com");
 pacientes.cadastrar(p);verificar(pacientes.buscar(1)==p,"cadastrar e consultar paciente");medicos.cadastrar(m);verificar(medicos.buscar(1)==m,"cadastrar e consultar médico");p.atualizarContato("11777777777","ana@exemplo.com","Nova Rua");pacientes.atualizar(p);verificar(pacientes.buscar(1).getEndereco().equals("Nova Rua"),"atualizar paciente");
 Convenio plano=new Convenio(1,"Saúde Vida","Enfermaria","0800-000",p);convenios.cadastrar(plano);verificar(p.isTemConvenio(),"associar convênio ao paciente");
 Consulta c=new Consulta(1,LocalDate.of(2027,1,20),LocalTime.of(14,30),p,m);consultas.agendar(c);verificar(c.getStatus()==Consulta.Status.AGENDADA,"agendar consulta");deveFalhar(()->consultas.agendar(new Consulta(2,c.getData(),c.getHora(),p,m)),"impedir conflito de horário");consultas.cancelar(1);verificar(c.getStatus()==Consulta.Status.CANCELADA,"cancelar consulta");
 Prontuario prontuario=new Prontuario(1,p);prontuarios.cadastrar(prontuario);prontuarios.adicionarRegistro(1,"Gripe","Orientações de repouso");verificar(prontuarios.buscar(1).consultar().contains("Gripe"),"registrar e consultar prontuário");deveFalhar(()->pacientes.cadastrar(p),"impedir cadastro duplicado");
 System.out.println("TOTAL: "+aprovados+" testes aprovados.");}}
